cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('data/order_summary.xlsx');
for (const name of wb.SheetNames) {
  const ws = wb.Sheets[name];
  const data = XLSX.utils.sheet_to_json(ws);
  const match = data.filter(row => Object.values(row).some(v => String(v).includes('ORD-6C71B1')));
  if (match.length > 0) {
    console.log('Sheet:', name);
    match.forEach(r => {
      for (const [k, v] of Object.entries(r)) {
        console.log('  ' + k + ': ' + v);
      }
    });
  }
}
"

